def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    remaining = 100 - n

    opp_d = opp.count('D')
    opp_c = n - opp_d

    # Endgame: exploit a bit when opponent is unlikely to punish much longer.
    if remaining <= 1:
        return 'D'

    recent_len = 8 if n >= 8 else n
    recent_opp = opp[-recent_len:]
    recent_opp_d = recent_opp.count('D')
    recent_opp_c = recent_len - recent_opp_d
    last_opp = opp[-1]

    # Last few rounds: defect if opponent has been defecting, otherwise keep cooperating.
    if remaining <= 3:
        if recent_opp_d >= 1:
            return 'D'
        return 'D' if rng.random() < 0.35 else 'C'

    # Pure or near-pure defector: don't keep feeding them.
    if n >= 6 and opp_c == 0:
        return 'D'
    if n >= 10 and opp_c <= n * 0.15:
        return 'D'

    # Pure cooperator: mostly keep cooperation, rare late probes for extra value.
    if n >= 5 and opp_d == 0:
        if n >= 40 and remaining > 10 and rng.random() < 0.02:
            return 'D'
        return 'C'

    # Strong recent defection pressure: punish, but periodically offer repair.
    if recent_opp_d >= max(3, recent_len - 2):
        if n >= 6 and opp[-3:] == ['D', 'D', 'D']:
            if rng.random() < 0.12:
                return 'C'
            return 'D'
        return 'D' if rng.random() < 0.88 else 'C'

    # If we just punished and opponent cooperated, accept the olive branch and cooperate.
    if n >= 2 and me[-1] == 'D' and last_opp == 'C':
        return 'C'

    # If opponent just defected after a mostly cooperative stretch, retaliate briefly.
    if last_opp == 'D':
        if recent_opp_d >= 2:
            return 'D'
        # Single isolated defection: punish once, then be ready to forgive.
        if n >= 2 and me[-1] == 'D':
            return 'C'
        return 'D'

    # Opponent just cooperated. Preserve cooperation unless overall exploitation is high.
    if last_opp == 'C':
        if n >= 12 and opp_d * 2 > n:
            if rng.random() < 0.25:
                return 'D'
            return 'C'
        if n >= 6 and recent_opp_c >= recent_len - 1:
            return 'C'
        if n >= 4 and opp[-2:] == ['C', 'C']:
            return 'C'
        return 'C'

    return 'C'
